<?php $purchasingSection='invoices';require dirname(__DIR__,2).'/components/admin/purchasing-nav.php';$labels=['draft'=>'Borrador','pending'=>'Pendiente','partial'=>'Recepción parcial','received'=>'Recibida','cancelled'=>'Cancelada']; ?>
<div class="purchasing-workspace"><section class="admin-page-head purchasing-page-head"><div><p class="admin-kicker">COMPRAS</p><h1>Facturas de proveedor</h1><p>Registrar el documento no modifica inventario. Solo una recepción física confirmada genera movimientos.</p></div><?php if($capabilities['purchases.create']??false):?><a class="admin-primary-button" data-admin-form-link href="/admin/purchases/create">+ Nueva factura</a><?php endif?></section>
<section class="purchasing-guide" aria-label="Proceso de compra"><div><span>01</span><div><h2>Registra la factura</h2><p>Captura el proveedor, el documento y sus partidas en un borrador.</p></div></div><div><span>02</span><div><h2>Confirma el documento</h2><p>Revisa los datos antes de habilitar la recepción de mercancía.</p></div></div><div><span>03</span><div><h2>Recibe la mercancía</h2><p>Confirma lo recibido físicamente para actualizar inventario.</p></div></div></section><section class="admin-panel purchasing-filters"><header><h2>Buscar facturas</h2><p>Encuentra documentos por proveedor, folio, sucursal o fecha.</p></header><form class="admin-filter-bar admin-purchase-filter" method="get" action="/admin/purchases"><?php if($supplierId!==null):?><input type="hidden" name="supplier_id" value="<?= e($supplierId) ?>"><?php endif?><label class="admin-field"><span>Buscar</span><input type="search" name="q" maxlength="120" value="<?= e($q) ?>" placeholder="Proveedor, serie o folio"></label><label class="admin-field"><span>Sucursal</span><select name="branch_id"><?php if($allBranches??false):?><option value="">Todas las sucursales</option><?php endif?><?php foreach($branches as$b):?><option value="<?= e($b['id']) ?>" <?= $branchId===(int)$b['id']?'selected':'' ?>><?= e($b['name']) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Estado</span><select name="status"><option value="all">Todos</option><?php foreach($labels as$k=>$v):?><option value="<?= e($k) ?>" <?= $status===$k?'selected':'' ?>><?= e($v) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Desde</span><input type="date" name="from" value="<?= e($from??'') ?>"></label><label class="admin-field"><span>Hasta</span><input type="date" name="until" value="<?= e($until??'') ?>"></label><div class="purchasing-filter-actions"><button class="admin-secondary-button">Aplicar filtros</button><?php if($q!==''||$status!=='all'||$branchId!==null||$from!==null||$until!==null||$supplierId!==null):?><a class="purchasing-text-link" href="/admin/purchases">Limpiar</a><?php endif?></div></form></section>
<section class="admin-panel admin-table-panel purchasing-directory"><header class="purchasing-directory-heading"><div><h2>Facturas registradas</h2><p>Consulta las partidas y el avance de recepción de cada documento.</p></div><span class="purchasing-page-count"><?= e(count($page->items)) ?> en esta página</span></header><?php if($page->items===[]):?><div class="purchasing-empty"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 3h10v18l-3-2-2 2-2-2-3 2V3Zm3 5h4m-4 4h4"/></svg><h3><?= ($q!==''||$status!=='all'||$from!==null||$until!==null||$supplierId!==null)?'Sin coincidencias':'Aún no hay facturas registradas' ?></h3><p><?= ($q!==''||$status!=='all'||$from!==null||$until!==null||$supplierId!==null)?'Prueba con otros filtros o limpia la búsqueda para ampliar los resultados.':'Comienza con una factura real de tu proveedor. Podrás agregar sus partidas y registrar la recepción cuando llegue la mercancía.' ?></p><div class="purchasing-empty-actions"><?php if($q!==''||$status!=='all'||$from!==null||$until!==null||$supplierId!==null):?><a class="admin-secondary-button" href="/admin/purchases">Limpiar filtros</a><?php elseif($capabilities['purchases.create']??false):?><a class="admin-primary-button" data-admin-form-link href="/admin/purchases/create">Registrar primera factura</a><?php endif?></div></div><?php else:?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Documento</th><th>Proveedor</th><th>Sucursal</th><th>Total</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($page->items as$i):?><tr><td data-label="Documento"><div><strong><?= e(trim($i['series'].' '.$i['folio'])) ?></strong><small><?= e($i['document_date'].' · '.$i['item_count'].' partidas') ?></small></div></td><td data-label="Proveedor"><div><?= e($i['supplier_name']) ?></div></td><td data-label="Sucursal"><?= e($i['branch_name']) ?></td><td data-label="Total"><?= e('$'.$i['total'].' MXN') ?></td><td data-label="Estado"><span class="admin-status <?= $i['status']==='received'?'is-active':'' ?>"><?= e($labels[$i['status']]??$i['status']) ?></span></td><td class="admin-actions"><a class="admin-secondary-button" data-admin-form-link href="/admin/purchases/detail?id=<?= e($i['id']) ?>">Detalle</a></td></tr><?php endforeach?></tbody></table></div><?php endif?></section>

<?php if($page->offset>0||$page->hasMore):?><nav class="admin-pagination" aria-label="Páginas de facturas"><?php foreach(['Anterior'=>max(0,$page->offset-25),'Siguiente'=>$page->offset+25] as $label=>$offset):?><?php if(($label==='Anterior'&&$page->offset>0)||($label==='Siguiente'&&$page->hasMore)):?><a href="?<?= e(http_build_query(['q'=>$q,'status'=>$status,'branch_id'=>$branchId,'supplier_id'=>$supplierId,'from'=>$from,'until'=>$until,'offset'=>$offset])) ?>"><?= e($label) ?></a><?php endif?><?php endforeach?></nav><?php endif?></div>
